    if (!g.blk[i]){ let n = 0; for (let k = 0; k < 16; k++){ const x = g.lon0 + (ix + ((k & 3) + 0.5) / 4) * g.step, y = g.lat0 + (iy + ((k >> 2) + 0.5) / 4) * g.step; if (enemySea("ru", [x, y])) n++; } if (n >= 6) g.blk[i] = 1; }
