  const P = p => [p[0] * kx, p[1] * ky], U = q => [q[0] / kx, q[1] / ky];
  const A = P(a), B = P(b), dx = B[0] - A[0], dy = B[1] - A[1], D = Math.hypot(dx, dy) || 1;
  const nx = -dy / D, ny = dx / D;
