OBLASTS.features.forEach(f => f.properties.side = f.properties.side || "ua");
RU_REGIONS.features.forEach(f => OBLASTS.features.push(f));
const OBL_SIDE = new Map(OBLASTS.features.map(f => [f.id, f.properties.side]));
/* етап 5.2: м. Київ — рівний (згладжений) контур; той самий контур вирізається «отвором» у Київській області,
   щоб місто й область стикувалися без щілин і накладань */
(function smoothKyiv(){
  const F = n => OBLASTS.features.find(f => f.properties.n === n);
  const city = F("м. Київ"), obl = F("Київська область"); if (!city || !obl) return;
  const area = R => { let s = 0; for (let i = 0, j = R.length - 1; i < R.length; j = i++) s += (R[j][0] - R[i][0]) * (R[j][1] + R[i][1]); return s; };
  const dp = (P, eps) => {
    if (P.length < 3) return P;
    const A = P[0], B = P[P.length - 1], vx = B[0] - A[0], vy = B[1] - A[1], L = Math.hypot(vx, vy) || 1e-12;
    let im = 0, dm = 0;
    for (let i = 1; i < P.length - 1; i++){ const d = Math.abs(vx * (P[i][1] - A[1]) - vy * (P[i][0] - A[0])) / L; if (d > dm){ dm = d; im = i; } }
    return dm > eps ? dp(P.slice(0, im + 1), eps).slice(0, -1).concat(dp(P.slice(im), eps)) : [A, B];
  };
  const src = city.geometry.coordinates[0][0], m = src.length >> 1;
  let R = dp(src.slice(0, m + 1), 0.022).slice(0, -1).concat(dp(src.slice(m), 0.022));
  for (let it = 0; it < 3; it++){
    const Q = [];
    for (let i = 0; i < R.length - 1; i++){ const p = R[i], q = R[i + 1]; Q.push([0.75 * p[0] + 0.25 * q[0], 0.75 * p[1] + 0.25 * q[1]], [0.25 * p[0] + 0.75 * q[0], 0.25 * p[1] + 0.75 * q[1]]); }
    Q.push(Q[0]); R = Q;
  }
  R = R.map(p => [+p[0].toFixed(5), +p[1].toFixed(5)]);
  const same = (X, Y) => Math.sign(area(X)) === Math.sign(area(Y)) ? Y : Y.slice().reverse();
  city.geometry.coordinates = [[same(src, R)]];
  // отвір у Київській області — найближче до центру міста внутрішнє кільце
  const c = [30.52, 50.45];
  for (const poly of obl.geometry.coordinates){
    for (let k = 1; k < poly.length; k++){
      const h = poly[k], hb = h.reduce((b, p) => [Math.min(b[0], p[0]), Math.min(b[1], p[1]), Math.max(b[2], p[0]), Math.max(b[3], p[1])], [180, 90, -180, -90]);
      if (c[0] > hb[0] && c[0] < hb[2] && c[1] > hb[1] && c[1] < hb[3]) poly[k] = same(h, R);
    }
  }
})();

const AD_CLASSES = [["drone", "БпЛА"], ["jet", "РБпЛА"], ["rd", "Ракетно-дронові"], ["cruise", "Крилаті ракети"], ["ballistic", "Балістичні ракети"], ["hyper", "Гіперзвукові ракети"],
  ["icbm", "Бойові блоки МБР"], ["bomb", "Авіабомби"], ["tac", "Тактичні БпЛА"], ["sea", "Морські дрони"]];      // етап 7.27: морські дрони — лише для корабельного ППО  // етап 7.11: дочірні частини МБР; етап 7.12: керовані авіабомби; етап 7.14: тактичні БпЛА
const AD_CI = Object.fromEntries(AD_CLASSES.map(([k], i) => [k, i]));
const AD_SPD = { "Надзвичайно висока": 48, "Надвисока": 40, "Дуже висока": 34, "Висока": 28 };     // км/с (ігрові) — швидкість ракет/снарядів ППО
const AD_MOVE_KMS = 3;
const SHIP_KMS = 4;               // етап 7.27: швидкість корабля ППО, км/с (ігрові)
/* етап 7.27: корабель ППО виходить з найближчого (морем) порту своєї сторони; маршрут — лише по воді */
const SHIP_START = new Map();
function shipStart(side, p, port){      // етап 7.28: port — назва військового порту, з якого виводять корабель (інакше — найближчий)
  if (enemySea(side, p)) return null;                 // етап 7.29: у чужі води кораблі не запливають
  const q = gSnap(seaGrid(side), p, 2); if (!q) return null;
  const key = side + ":" + (port || "") + ":" + q[0].toFixed(2) + "," + q[1].toFixed(2);
  if (SHIP_START.has(key)) return SHIP_START.get(key);
  let best = null;
  for (const s of SITES){
    if (s.off || s.t !== (side === "ru" ? "port" : "ua_port") || (port && s.n !== port)) continue;
    if (!portSea(s)) continue;
    const path = portPath(s, q); if (!path || path.length < 2) continue;
    const L = polyLen(path); if (!best || L < best.L) best = { port: s.n, path, L, exitN: s.exit ? s.exit.length : 0 };
  }
  if (SHIP_START.size > 400) SHIP_START.clear();
  SHIP_START.set(key, best);
  return best;
}
/* новий курс корабля; якщо корабель ще йде річкою з порту (Дунай) — спершу до моря тим самим шляхом */
function shipRoute(from, to, u){
  const side = (u && u.side) || "ua", g = seaGrid(side);
  if (enemySea(side, to)) return null;                // етап 7.29: лише свої води
  const q = gSnap(g, to, 2); if (!q) return null;
  if (!gSnap(g, from, 4)){
    if (!u || !u.mPath || !u.exitN || u.mi >= u.exitN) return null;
    const rest = [from.slice()].concat(u.mPath.slice(u.mi, u.exitN).map(x => x.slice()));
    const r = seaRouteS(side, rest[rest.length - 1], q); if (!r || r.length < 2) return null;
    const out = rest.concat(r); out.exitN = rest.length; return out;
  }
  const r = seaRouteS(side, from, q); return r && r.length >= 2 ? r : null;
}
function shipGo(u, path){
  u.state = "move"; u.mPath = path.map(x => x.slice()); u.mFrom = path[0].slice(); u.mTo = path[path.length - 1].slice(); u.ms = 0; u.mL = Math.max(0.01, polyLen(path)); u.mi = 1; u.engaged = u.engaged || null; ADS.dirty = true;
}
function shipStep(u, sd){
  let step = SHIP_KMS * sd;
  while (step > 1e-6 && u.mi < u.mPath.length){
    const nx = u.mPath[u.mi], d = hav(u.pos, nx);
    if (d > 1e-4) u.hdg = brg(u.pos, nx);
    if (d <= step){ u.pos = nx.slice(); step -= d; u.mi++; }
    else { u.pos = moveToward(u.pos, nx, step); step = 0; }
  }
  if (u.mi >= u.mPath.length){ u.pos = u.mTo.slice(); u.state = "ready"; u.cool = Math.min(u.cool || 0, 0.5); u.mPath = null; }
}                                 // швидкість переміщення установки, км/с (ігрові)
