Object.values(AD_TYPES).forEach(T => { T.side = T.side || "ua"; });
/* етап 7.11: бойові блоки МБР збити трохи важче, ніж гіперзвукові ракети (≈ 85% від шансу по гіперзвуку) */
/* етап 7.12: керовані авіабомби — трохи важче, ніж крилаті ракети (≈ 85% від шансу по крилатих) */
const pk85 = v => v >= 10 ? Math.round(v * 0.85) : Math.round(v * 85) / 100;
Object.values(AD_TYPES).forEach(T => { if (T.p.length < 7) T.p.push(Math.round(T.p[5] * 0.85)); if (T.p.length < 8) T.p.push(pk85(T.p[3])); });
/* етап 7.14: тактичні БпЛА (малі, низькі) — ≈ 90% від шансу по БпЛА */
Object.values(AD_TYPES).forEach(T => { if (T.p.length < 9) T.p.push(T.p[0] >= 10 ? Math.round(T.p[0] * 0.9) : Math.round(T.p[0] * 90) / 100); });
Object.values(AD_TYPES).forEach(T => { if (T.ship) T.p[9] = T.sea || 0; });      // етап 7.27: морські дрони — лише корабельне ППО
/* етап 7.30: однаковий розмір — наземні ППО, дрони-перехоплювачі, кораблі, авіація (як і носії: літаки — SZ_AIR, кораблі — SZ_SHIP) */
for (const T of Object.values(AD_TYPES)) T.sz = T.ship ? SZ_SHIP : T.air ? SZ_AIR : T.drone ? 28 : 31;
const AD_ORDER = Object.keys(AD_TYPES).filter(k => !AD_TYPES[k].air && AD_TYPES[k].side === "ua");
const AD_ORDER_RU = Object.keys(AD_TYPES).filter(k => !AD_TYPES[k].air && AD_TYPES[k].side === "ru");
const AIR = { cruise: 7, chase: 11, turn: 55, orbit: 14, leash: 75, arc: 35, detect: 2.4,   // км/с (ігрові), °/с, км, півкут сектора °
              aim: 160, rof: 0.45, lock: 2 };   // етап 7.33: lock — тривале наведення: ціль у секторі від носа 2 с поспіль, лише тоді — ракета   // етап 5.5: швидке наведення носа на ціль (°/с) і інтервал між пусками (с)
/* етап 7.23: швидкість і маневреність — свої в кожного типу авіації (Су-27 і МіГ-29 — як і раніше) */
const AIR_FLY = { "Надвисока": 1, "Дуже висока": 0.92, "Висока": 0.85, "Середня": 0.5, "Низька": 0.4 };
const AIR_MAN = { "Дуже висока": 1.25, "Висока": 1, "Середня": 0.8, "Низька": 0.65 };
const airK = T => (T && AIR_FLY[T.fly]) || 1, airM = T => (T && AIR_MAN[T.man]) || 1;
const airArc = T => (T && T.arc) || AIR.arc, airOrbit = T => Math.max(5, AIR.orbit * airK(T));
const AIR_KEYS = { ua: Object.keys(AD_TYPES).filter(k => AD_TYPES[k].air && AD_TYPES[k].side === "ua"), ru: Object.keys(AD_TYPES).filter(k => AD_TYPES[k].air && AD_TYPES[k].side === "ru") };
const adSrc = key => { const T = AD_TYPES[key]; return T && T.air ? SPRITES[T.img].src : AD_SPRITES["ad_" + key].src; };
