const ALERT_T = { yellow: { n: "Жовта", d: "БпЛА / РБпЛА", c: "#ffd21a" }, red: { n: "Червона", d: "ракети та інші", c: "#ff2a2a" } };

const OCC_BB = BV.occupied.geometry.coordinates.map(poly => {
  let a = [180, 90, -180, -90];
  for (const [x, y] of poly[0]){ if (x < a[0]) a[0] = x; if (y < a[1]) a[1] = y; if (x > a[2]) a[2] = x; if (y > a[3]) a[3] = y; }
  return { poly, bb: a };
});
function inPoly(p, rings){
  let ins = false;
  for (const ring of rings) for (let i = 0, j = ring.length - 1; i < ring.length; j = i++){
    const xi = ring[i][0], yi = ring[i][1], xj = ring[j][0], yj = ring[j][1];
    if (((yi > p[1]) !== (yj > p[1])) && (p[0] < (xj - xi) * (p[1] - yi) / (yj - yi) + xi)) ins = !ins;
  }
  return ins;
}
const inOccupiedUA = p => OCC_BB.some(o => p[0] >= o.bb[0] && p[0] <= o.bb[2] && p[1] >= o.bb[1] && p[1] <= o.bb[3] && inPoly(p, o.poly));
const canPlaceAD = p => inUkraine(p) && !inOccupiedUA(p);
/* етап 7.34: чия територія в точці (для кольору доріг і колій): "ua" — підконтрольна Україні, "ru" — Росія й окупована, "" — море / інша країна; кеш ≈1 км */
const TERR_C = new Map();
/* швидка перевірка «точка в полігоні»: ребра, розкладені за смугами широти (0,05°) — для тисяч точок уздовж доріг і колій */
function bandIndex(rings, h){
  let y0 = Infinity, y1 = -Infinity; for (const r of rings) for (const q of r){ if (q[1] < y0) y0 = q[1]; if (q[1] > y1) y1 = q[1]; }
  const n = Math.ceil((y1 - y0) / h) + 1, B = Array.from({ length: n }, () => []);
  for (const r of rings) for (let i = 0, j = r.length - 1; i < r.length; j = i++){
    const a = r[j], c = r[i], lo = Math.floor((Math.min(a[1], c[1]) - y0) / h), hi = Math.floor((Math.max(a[1], c[1]) - y0) / h);
    for (let k = lo; k <= hi; k++) B[k].push(a[0], a[1], c[0], c[1]);
  }
  return { y0, h, B: B.map(x => new Float64Array(x)) };
}
function bandIn(I, p){
  const k = Math.floor((p[1] - I.y0) / I.h); if (k < 0 || k >= I.B.length) return false;
  const e = I.B[k], x = p[0], y = p[1]; let ins = false;
  for (let i = 0; i < e.length; i += 4){ const xj = e[i], yj = e[i + 1], xi = e[i + 2], yi = e[i + 3]; if (((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi)) ins = !ins; }
  return ins;
}
let TERR_I = null;
function terrAt(p){
  const k = Math.round(p[0] * 100) * 100000 + Math.round(p[1] * 100); let v = TERR_C.get(k); if (v !== undefined) return v;
  if (!TERR_I) TERR_I = { ua: bandIndex(BV.uaOutline.geometry.coordinates, 0.05), occ: bandIndex(BV.occupied.geometry.coordinates.flat(), 0.05) };
  v = bandIn(TERR_I.ua, p) ? (bandIn(TERR_I.occ, p) ? "ru" : "ua") : !foreignAt(p) && inRussiaGrid(p) ? "ru" : "";
  if (TERR_C.size > 200000) TERR_C.clear(); TERR_C.set(k, v); return v;
}
function cityNear(p, r){
  let best = null, bd = 1e9;
  for (const c of CITIES.concat(RU_CITIES, OCC_CITIES)){ const d = hav(p, [c[1], c[2]]); if (d < bd){ bd = d; best = c[0]; } }
  return bd < (r || 25) ? "р-н м. " + best : fmtLL(p);
}
function circlePoly(c, km, n){
  const pts = [], kx = 111.32 * Math.cos(c[1] * D2R), ky = 110.574;
  for (let i = 0; i <= n; i++){ const a = i / n * 2 * Math.PI; pts.push([c[0] + km / kx * Math.cos(a), c[1] + km / ky * Math.sin(a)]); }
  return pts;
}
function moveToward(a, b, km){
  const kx = 111.32 * Math.cos(a[1] * D2R), ky = 110.574;
  const dx = (b[0] - a[0]) * kx, dy = (b[1] - a[1]) * ky, d = Math.hypot(dx, dy) || 1;
  return [a[0] + dx / d * km / kx, a[1] + dy / d * km / ky];
}

/* ---------- state ---------- */
const ADS = { units: new Map(), shots: [], rounds: [], uid: 1, kills: 0, damaged: 0, destroyed: 0, leaks: 0, fired: 0, dirty: true,
              ruKills: 0, uaHits: 0, ships: 0 };   // ruKills — збито авіацією ППО Росії, uaHits — влучань по Росії, ships — знищено кораблів
const ALERTS = new Map();      // id області → { type, t0, auto }
const AUTO_AL = { on: false, onRu: false, last: new Map(), lastRed: new Map(), tick: 0, HOLD: 8, LOOK: 12 };   // on — Україна, onRu — Росія
const autoOn = side => side === "ru" ? AUTO_AL.onRu : AUTO_AL.on;
const OBL_BB = OBLASTS.features.map(f => {
  let a = [180, 90, -180, -90];
  for (const poly of f.geometry.coordinates) for (const [x, y] of poly[0]){ if (x < a[0]) a[0] = x; if (y < a[1]) a[1] = y; if (x > a[2]) a[2] = x; if (y > a[3]) a[3] = y; }
  return { id: f.id, polys: f.geometry.coordinates, bb: a };
});
function oblastsOf(p){
  const out = [];
  for (const o of OBL_BB){
    if (p[0] < o.bb[0] || p[0] > o.bb[2] || p[1] < o.bb[1] || p[1] > o.bb[3]) continue;
    for (const poly of o.polys) if (inPoly(p, poly)){ out.push(o.id); break; }
  }
  return out;
}
function routePointAt(u, s){
  const c = u.cum; let i = Math.min(u.seg || 0, c.length - 2);
  while (i < c.length - 2 && c[i + 1] < s) i++;
  const a = u.pts[i], b = u.pts[i + 1] || a, t = Math.max(0, Math.min(1, (s - c[i]) / ((c[i + 1] - c[i]) || 1)));
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}
/* загроза для областей: де ціль зараз і куди долетить за найближчі LOOK секунд */
function alertThreats(){
  const th = new Map();
  for (const u of units.values()){
    if (u.kind !== "w" || u.fall || u.sea) continue;
    const tside = u.sd === "ru" ? "ua" : "ru";
    if (fogLive() && !fogKnownThreat(tside, u)) continue;      // етап 7.60: тривога лише за цілями, виявленими РЛС сторони, що обороняється                    // цілі Росії → тривоги в Україні, цілі України → тривоги в Росії
    const cls = WEAPONS[u.key].ad, lvl = cls === "drone" || cls === "jet" ? 1 : 2;
    const look = Math.max(25, u.spd * AUTO_AL.LOOK), end = Math.min(u.L, u.s + look);
    for (let s = u.s; ; s = Math.min(end, s + 8)){
      for (const id of oblastsOf(s === u.s ? u.pos : routePointAt(u, s))) if (OBL_SIDE.get(id) === tside && (th.get(id) || 0) < lvl) th.set(id, lvl);
      if (s >= end) break;
    }
  }
  return th;
}

/* ---------- icons ---------- */
