/* ---------- textures ---------- */
const TEX = {};
function prng(seed){ let s = seed >>> 0 || 1; return () => (s = (s * 1664525 + 1013904223) >>> 0) / 4294967296; }
function blobTex(size, n, spread, rmin, rmax, col, seed){
  const c = document.createElement("canvas"); c.width = c.height = size;
  const g = c.getContext("2d"), r = prng(seed);
  for (let i = 0; i < n; i++){
    const ang = r() * Math.PI * 2, dist = Math.pow(r(), 0.7) * spread * size;
    const x = size / 2 + Math.cos(ang) * dist, y = size / 2 + Math.sin(ang) * dist, rad = size * (rmin + r() * (rmax - rmin));
    const [cr, cg, cb, ca] = col(r());
    const gr = g.createRadialGradient(x, y, 0, x, y, rad);
    gr.addColorStop(0, `rgba(${cr},${cg},${cb},${ca})`); gr.addColorStop(0.55, `rgba(${cr},${cg},${cb},${ca * 0.45})`); gr.addColorStop(1, `rgba(${cr},${cg},${cb},0)`);
    g.fillStyle = gr; g.beginPath(); g.arc(x, y, rad, 0, 7); g.fill();
  }
  return c;
}
/* рвана, витягнута хмарка (не ідеальне коло) */
function cloudTex(size, n, col, seed){
  const c = document.createElement("canvas"); c.width = c.height = size;
  const g = c.getContext("2d"), r = prng(seed);
  for (let i = 0; i < n; i++){
    const t = r() * 2 - 1, x = size / 2 + t * size * 0.27 + (r() - 0.5) * size * 0.08;
    const y = size / 2 + (r() - 0.5) * size * 0.26 * (1 - Math.abs(t) * 0.55) + Math.sin(t * 3 + r()) * size * 0.04;
    const rad = size * (0.06 + r() * 0.14) * (1 - Math.abs(t) * 0.35);
    const [cr, cg, cb, ca] = col(r());
    const gr = g.createRadialGradient(x, y, 0, x, y, rad);
    gr.addColorStop(0, `rgba(${cr},${cg},${cb},${ca})`); gr.addColorStop(0.5, `rgba(${cr},${cg},${cb},${ca * 0.5})`); gr.addColorStop(1, `rgba(${cr},${cg},${cb},0)`);
    g.fillStyle = gr; g.beginPath(); g.arc(x, y, rad, 0, 7); g.fill();
  }
  return c;
}
function buildTex(){
  if (TEX.ok) return;
  TEX.smoke = [0, 1, 2, 3, 4].map(i => cloudTex(128, 26, v => { const l = 128 + v * 40 | 0; return [l, l - 1, l - 5, 0.24]; }, 11 + i * 7));
  TEX.dark = [0, 1, 2, 3].map(i => cloudTex(128, 26, v => { const l = 64 + v * 34 | 0; return [l + 5, l, l - 4, 0.27]; }, 101 + i * 13));
  TEX.dust = [0, 1].map(i => blobTex(96, 18, 0.17, 0.12, 0.3, v => [150 + v * 30 | 0, 136 + v * 24 | 0, 112 + v * 18 | 0, 0.3], 201 + i * 5));
  TEX.fire = [0, 1, 2].map(i => blobTex(96, 18, 0.14, 0.12, 0.28, v => v < 0.3 ? [255, 244, 200, 0.6] : v < 0.7 ? [255, 172, 62, 0.5] : [232, 92, 32, 0.45], 301 + i * 17));
  const f = document.createElement("canvas"); f.width = f.height = 96;
  const g = f.getContext("2d"), gr = g.createRadialGradient(48, 48, 0, 48, 48, 48);
  gr.addColorStop(0, "rgba(255,255,248,1)"); gr.addColorStop(0.18, "rgba(255,246,205,0.92)"); gr.addColorStop(0.45, "rgba(255,190,92,0.45)"); gr.addColorStop(1, "rgba(255,120,40,0)");
  g.fillStyle = gr; g.fillRect(0, 0, 96, 96);
  TEX.flash = f; TEX.ok = true;
}

/* ---------- particles & emitters ---------- */
function P(o){
  const now = performance.now();
  const q = Object.assign({ k: "tex", t0: now, v: [0, 0], tau: Infinity, wind: false, rot: Math.random() * 6.283, vr: 0, a0: 1, pw: 1.2, fin: 0.06,
    s0: 0.05, s1: 0.1, m0: 2, m1: 4, add: false }, o);
  if (q.wind){
    // завихрення й турбулентність: бічне розсіювання, коливання, розтягування вздовж вітру
    q.sd = rnd(-0.07, 0.07); q.tb = rnd(0.06, 0.18); q.sf = rnd(0.5, 1.5); q.sp = rnd(0, 6.283); q.st = rnd(0.8, 1.8);
    q.rot = rnd(-0.4, 0.4); q.vr = rnd(-0.08, 0.08);
  }
  FX.parts.push(q);
  if (FX.parts.length > 2600) FX.parts.splice(0, FX.parts.length - 2600);
}
