const jitter = (p, km) => offKm(p, rnd(-km, km), rnd(-km, km));
const dirV = (ang, sp) => [Math.sin(ang) * sp, Math.cos(ang) * sp];

function fxFlash(p, s0, s1, m0, m1, life){ P({ tex: TEX.flash, p, life, s0, s1, m0, m1, a0: 1, pw: 1.7, fin: 0.04, add: true, rot: 0 }); }
