window.BV_AIRX = AIRX;
const AIR_END = { aew_saab340: 600, aew_a50: 780, su27: 360, mig29: 240, su30: 420, su35: 360, f16: 330, mirage: 250, mi24: 420, mi8: 520, mi28: 480, ka52: 480 };
