      map.addSource("ewz", { type: "geojson", data: { type: "FeatureCollection", features: [] } });
      map.addSource("ewp", { type: "geojson", data: { type: "FeatureCollection", features: [] } });
      map.addLayer({ id: "ewz-f", type: "fill", source: "ewz", paint: { "fill-color": ["get", "c"], "fill-opacity": ["case", ["==", ["get", "a"], 1], 0.1, 0.03] } });
      map.addLayer({ id: "ewz-l", type: "line", source: "ewz", paint: { "line-color": ["get", "c"], "line-width": 1.2, "line-opacity": 0.8, "line-dasharray": [3, 2] } });
      map.addLayer({ id: "ewp-c", type: "circle", source: "ewp", paint: { "circle-radius": 6, "circle-color": ["get", "c"], "circle-stroke-color": ["case", ["==", ["get", "sn"], 1], "#ff3b3b", "#ffffff"], "circle-stroke-width": 2, "circle-opacity": ["case", ["==", ["get", "a"], 1], 1, 0.45] } });
      map.on("click", "ewp-c", e => { const f = e.features && e.features[0]; if (f) { ewPop(+f.properties.id); } });
      map.on("mouseenter", "ewp-c", () => { map.getCanvas().style.cursor = "pointer"; });
      map.on("mouseleave", "ewp-c", () => { map.getCanvas().style.cursor = ""; });
      map.on("click", e => { if (!EW.pick) return; const p = [e.lngLat.lng, e.lngLat.lat]; const st = ewAdd(EW.pick, p, EW.side, false); if (st){ toast(`РЕБ «${EWSYS[st.key].n}»: розгортання ${EWSYS[st.key].rdy} с`); EW.pick = null; map.getCanvas().style.cursor = ""; ewPanel(); } else toast(EW.side === "ua" ? "Станцію можна ставити лише на підконтрольній Україні території" : "Станцію можна ставити лише на території Росії та окупованій території"); });
