        pf.push({ type: "Feature", properties: { id: d.id, r: 5, c: col, s: TEL_LV[d.level] || "#9aa4b2", o: d.stale ? 0.35 : 0.8 }, geometry: { type: "Point", coordinates: d.pos } });
