HOOKS.adSkip = (u, T, t) => radarAdSkip(u, T, t) || adSkip(u, T, t);      // етап 7.55: ЗРК б'ють лише за захопленням РЛС
/* літаком керує гравець (не бот) — у польоті тримає заданий курс */
HOOKS.holdCourse = u => !BOT[u.side || "ua"];
/* етап 7.19: дрон P1-Sun наводиться сам лише тоді, коли стороною керує бот */
HOOKS.p1Auto = sd => !!(GAME.on && BOT[sd]);
/* етап 7.20: підказка гравцеві сторони (P1-Sun: ціль у зоні ураження — оберіть її в панелі) */
HOOKS.adHint = (sd, msg) => { if (!GAME.on) toast(msg); else if (!BOT[sd]) sideToast(sd, msg); };
/* авіація бота: зліт лише на повітряні цілі поблизу, повернення — коли небо чисте */
const AIR_SCR = 170, AIR_CLEAR = 230;
function botAirStep(sd, dt){
  const tg = [];
  for (const t of units.values()) if (t.kind === "w" && !t.fall && !t.inv && t.sd !== sd && WEAPONS[t.key] && WEAPONS[t.key].ad) tg.push(t);
  const per = (DIFF[GAME.diff] || DIFF.normal).air, busy = new Map();
  const planes = [...ADS.units.values()].filter(u => u.side === sd && AD_TYPES[u.key].air && !AD_TYPES[u.key].aew);   // етап 8: ДРЛО бот не керує
  for (const u of planes) if (u.botT && units.has(u.botT)) busy.set(u.botT, (busy.get(u.botT) | 0) + 1);
  for (const u of planes){
    const T = AD_TYPES[u.key];
    u.botCd = Math.max(0, (u.botCd || 0) - dt);
    if (u.state === "reload") continue;
    const air = u.state === "transit" || u.state === "patrol";
    if (u.state === "base"){
      if (u.mag < T.mag && u.reserve > 0){ HOOKS.adAct("reload", { id: u.id }); continue; }
      if (u.mag <= 0) continue;
    }
    if (u.state === "rtb" && u.mag <= 0) continue;
    // найближча ціль, до якої можна летіти, — від аеродрому (на землі) або від літака (у повітрі)
    const from = air ? u.pos : u.home;
    let best = null, bd = Infinity;
    for (const t of tg){
      if (!(T.p[AD_CI[WEAPONS[t.key].ad]] > 0) || !patrolOK(sd, t.pos) || adSkip(u, T, t)) continue;
      const d = hav(from, t.pos) + (busy.get(t.id) | 0) * 60; if (d < bd){ bd = d; best = t; }
    }
    if (air){
      const clear = !best || hav(u.pos, best.pos) > AIR_CLEAR;
      u.botIdle = clear ? (u.botIdle || 0) + dt : 0;
      if (u.botIdle > 45){ u.botIdle = 0; u.botT = null; HOOKS.adAct("rtb", { id: u.id }); continue; }
      // ціль далеко від точки патрулювання і літак не зайнятий — перенацілити
      if (best && !u.engaged && u.botCd <= 0 && hav(best.pos, u.patrol) > AIR.leash * 0.8 && hav(u.pos, best.pos) < AIR_SCR * (T.heli ? 0.45 : 1) * 1.3){
        if (HOOKS.adAct("airCmd", { id: u.id, p: best.pos.slice() })){ u.botT = best.id; u.botCd = 25; busy.set(best.id, (busy.get(best.id) | 0) + 1); }
      }
      continue;
    }
    if (u.state === "rtb") continue;
    // на землі: зліт, якщо ціль поруч і на неї ще не вилетіло достатньо літаків
    if (best && hav(u.home, best.pos) <= AIR_SCR * (T.heli ? 0.45 : 1) && (busy.get(best.id) | 0) < per && u.botCd <= 0){     // етап 7.23: вертольоти — лише на близькі цілі
      if (HOOKS.adAct("airCmd", { id: u.id, p: best.pos.slice() })){ u.botT = best.id; u.botCd = 20; u.botIdle = 0; busy.set(best.id, (busy.get(best.id) | 0) + 1); }
    }
  }
}
/* вікно атаки бота: ніч / раунд — повністю; у «Дуелі» — кожна доба окремо (запас ділиться на дні, що лишилися) */
const FREE_CYC = 480;          // етап 7.18: бот у полігоні — цикли атаки по 8 ігрових годин
function botWin(B){
  const M = MODES[GAME.mode];
  if (M.kind === "free"){
    const b0 = B && B.t0 != null ? B.t0 : GAME.start, d = Math.max(0, Math.floor((GAME.clock - b0) / FREE_CYC)), s = b0 + d * FREE_CYC;
    return { id: "f" + d, s: s + 2, e: s + FREE_CYC - 25, left: 1 };
  }
  if (M.kind === "days"){
    const d = Math.max(0, Math.floor((GAME.clock - GAME.start) / 1440)), s = GAME.start + d * 1440;
    return { id: "d" + d, s: s + 15, e: Math.min(s + 1440 - 40, GAME.end - 30), left: Math.max(1, (M.days || 1) - d) };
  }
  return { id: "r" + (GAME.round | 0), s: GAME.start, e: GAME.end - 70, left: 1 };
}
let botAirAcc = 0;
function botsStep(dt){
  botAirAcc += dt || 0;
  const airTick = botAirAcc >= 3; if (airTick){ for (const sd of ["ua", "ru"]) if (BOT[sd] && (adOn(sd) || GAME.mode === "free")) botAirStep(sd, botAirAcc); botAirAcc = 0; }
  for (const sd of ["ua", "ru"]){
    const B = BOT[sd]; if (!B || GAME.clock < B.next) continue;
    const M = MODES[GAME.mode], D = DIFF[GAME.diff] || DIFF.normal;
    if (!canAttack(sd)){ B.next = GAME.clock + 15; continue; }
    const W = botWin(B), free = M.kind === "free", stk = botArs(sd);
    if (GAME.clock > W.e){ B.next = M.kind === "days" ? W.s + 1440 : M.kind === "rounds" ? GAME.end : free ? W.s - 2 + FREE_CYC : Infinity; continue; }   // у «Календарі» — знову в наступному раунді атаки
    if (B.win !== W.id){
      // новий цикл атаки: бюджет пусків на цей цикл
      B.win = W.id; B.bud = {}; B.sent = {}; B.last = {}; B.focus = null;
      // етап 7.43: бот не застосовує міжконтинентальну зброю (Орєшнік — окремо: шанс, не більше одного за атаку)
      for (const k in stk){ const n = stk[k] | 0; B.last[k] = n; if (n > 0 && !ICBM_KEYS.includes(k)) B.bud[k] = Math.max(1, Math.round(n * D.use / W.left)); }
      botScen(sd, B, W);
    } else if (!free){
      // етап 7.5: вироблене заводами за цей час — теж у бюджет поточного циклу
      for (const k in GAME.stock[sd]){ if (ICBM_KEYS.includes(k)) continue; const n = GAME.stock[sd][k] | 0, l = B.last[k] | 0; if (n > l) B.bud[k] = (B.bud[k] | 0) + Math.max(1, Math.round((n - l) * D.use)); }
    }
    const night = M.kind === "night" || M.kind === "rounds" || free;
    const gap = (night ? 30 : 75) * D.gap * ((B.sc && B.sc.gapK) || 1);
    B.cache = null;
    botWave(sd, W, gap);
    B.last = {}; for (const k in stk) B.last[k] = stk[k] | 0;
    B.next = GAME.clock + gap * (0.8 + Math.random() * 0.4);
  }
}
function botPhase(W){
  const x = Math.min(0.9999, Math.max(0, (GAME.clock - W.s) / Math.max(1, W.e - W.s)));
  let p = 0; for (let i = 0; i < BOT_PH.length; i++) if (x >= BOT_PH[i].t) p = i;
  return { x, p };
}
function botWave(sd, W, gap){
  const B = BOT[sd]; if (!B) return;
  const { x, p } = botPhase(W), ph = BOT_PH[p], gf = gap / Math.max(1, W.e - W.s), S = B.sc || {};
  B.x = x;
  if (B.ore && !B.ore.done && x >= B.ore.at){ B.ore.done = true; botOreshnik(sd); }      // етап 7.43: Орєшнік — один за атаку
  if (S.pause && x >= S.pause[0] && x < S.pause[1]) return;                               // «тиша перед ударом»
  let cmds = 0;
  const keys = Object.keys(B.bud).filter(k => B.bud[k] > 0 && botHas(sd, k) > 0 && ph.c.includes(wCls(k)));
  for (const key of keys.sort(() => Math.random() - 0.5)){
    const cls = wCls(key), have = Math.min(B.bud[key], botHas(sd, key));
    // скільки «зважених хвиль» ще лишилося для цього класу до кінця його фаз
    let rem = 0;
    for (let q = p; q < BOT_PH.length; q++){ if (!BOT_PH[q].c.includes(cls)) continue; const a = q === p ? x : BOT_PH[q].t; rem += Math.max(0, phEnd(q) - a) / gf * BOT_PH[q].k; }
    let frac = rem <= ph.k * 1.05 ? 1 : ph.k / rem;
    if (S.decoy && isDecoy(key) && x >= 0.45 && x < 0.67) frac = 1;                        // «приманки попереду»: усі приманки — перед ракетами
    let take;
    if (frac >= 1) take = have;
    else { const v = have * frac * (0.8 + Math.random() * 0.4); take = Math.floor(v) + (Math.random() < v - Math.floor(v) ? 1 : 0); }
    take = Math.min(have, take);
    const Wp = WEAPONS[key], maxB = Math.round((Wp.ad === "drone" ? 30 : Wp.ad === "jet" || Wp.ad === "rd" ? 8 : Wp.mirv || Wp.km > 5000 ? 2 : 6) * (S.batK || 1));
    while (take > 0 && cmds < (frac >= 1 ? 24 : 12) * (S.batK ? 1.5 : 1)){
      const n = Math.min(take, maxB);
      if (!botLaunch(sd, key, n)) break;
      take -= n; cmds++; B.bud[key] = Math.max(0, B.bud[key] - n);
    }
  }
}
/* етап 7.5: стратегічний вибір цілі — будь-який об'єкт противника за цінністю: заводи (що більший склад, то цінніші;
   заводи ППО — коли противник обороняється, заводи зброї — коли він атакує), пункти ППО, аеродроми, рубежі, порти,
   міста (столиця й обласні центри — цінніші, повторні удари по тому ж місту — менш вигідні).
   Добивання пошкоджених, без «перебору» (не шле на ціль більше, ніж треба), дешеві БпЛА — в обхід щільної ППО
   (приманки «Гербера» — навпаки, на прикриті цілі), балістика й гіперзвук — по найцінніших */
const ATK_V = { post: 21, air: 18, fighter: 21, strat: 24, port: 19, launch: 15, lport: 24, lrail: 17, llog: 15 };
function objValue(o){
  const foe = o.side;
  let v;
  if (o.t === "fac"){
    const inv = GAME.facInv && GAME.facInv[o.fi]; let m = 0;
    if (inv) for (const p in inv) if (ECO_PI[p]) m += inv[p] / ECO_PI[p].q * ECO_PI[p].$;
    const adT = o.ft === "adl" || o.ft === "sam" || o.ft === "abm" || o.ft === "gun";
    v = 12 + Math.min(22, Math.sqrt(m) * 2.2) + (adT ? (adOn(foe) ? 5 : -5) : (MODES[GAME.mode].ars && MODES[GAME.mode].ars[foe] ? 4 : -5));
    const S = GAME.facSel && GAME.facSel[o.fi]; if (S && S.on) v += 3;
  } else if (o.t === "city"){
    const n = (GAME.cityHits && GAME.cityHits[o.i]) | 0;
    v = [26, 17, 10, 6][objTier(o)] / (1 + n * 0.12);
  } else if (o.inf != null){                                         // етап 7.43: урядові будівлі, НПЗ, ТЕЦ
    v = infValue(o);
  } else if (o.li != null){                                          // логістика: що більше деталей на вузлі — то цінніше
    const V = GAME.lgv; v = (ATK_V[o.t] || 14) + (V ? Math.min(20, Math.sqrt((V.f[o.li] || 0) + (V.h[o.li] || 0)) * 1.3) : 0);
  } else v = ATK_V[o.t] || 12;
  if (o.t !== "city" && GAME.obj[o.i] < o.hp - 0.01) v *= 1.35;       // добити пошкоджене
  return Math.max(1, v);
}
function botCache(sd){
  const B = BOT[sd];
  if (B.cache) return B.cache;
  const foe = other(sd), list = OBJS.filter(o => o.side === foe && (o.t === "city" || GAME.obj[o.i] > 0));
  const def = new Map();
  for (const o of list){
    let n = 0;
    for (const u of ADS.units.values()){ if (u.side !== foe) continue; const T = AD_TYPES[u.key]; if (T.air || T.gun) continue; if (hav(u.pos, o.c) <= T.r) n++; }
    def.set(o.i, n);
  }
  return (B.cache = { list, def, val: new Map(list.map(o => [o.i, objValue(o)])) });
}
function botTarget(sd, key, reach){
  const B = BOT[sd], C = botCache(sd), cls = wCls(key), dmg = wDmg(key);
  if (!C.list.length) return null;
  // етап 7.10: ракети малої дальності (Точка-У, Х-31, Х-59…) — лише по цілях, до яких вони дістають
  const inReach = o => !reach || (typeof reach === "function" ? reach(o) : reach.some(q => hav(q, o.c) <= q[2]));   // етап 7.12: або функція (авіабомби)
  if (!B.focus) B.focus = C.list.filter(o => o.t !== "city").map(o => [o, C.val.get(o.i) * botScW0(B, o)]).sort((a, b) => b[1] - a[1]).slice(0, 3).map(x => x[0].i);
  const sc = o => {
    let v = C.val.get(o.i) * botScW(B, o, key, cls);                          // етап 7.43: сценарій атаки
    const d = C.def.get(o.i) | 0;
    if (isDecoy(key)) v *= 1 + d * 0.12;                                       // приманки — туди, де ППО
    else if (cls === "drone" || cls === "tac") v /= 1 + d * 0.12;
    else if (cls === "jet" || cls === "rd") v /= 1 + d * 0.07;
    else if (cls === "cruise" || cls === "bomb") v /= 1 + d * 0.05;
    else v = Math.pow(v, 1.25);                                                // балістика / гіперзвук — найцінніше
    if (WEAPONS[key].arm && o.t === "post") v *= 2.2;                          // протирадіолокаційні — по радарах ППО
    if (WEAPONS[key].ship && (o.t === "lport" || o.t === "port")) v *= 1.8;     // протикорабельні — по портах
    if (o.t !== "city"){ const sent = (B.sent && B.sent[o.i]) || 0; if (sent > GAME.obj[o.i] * 2.2) v *= 0.25; }
    if (B.focus.includes(o.i) && GAME.obj[o.i] > 0) v *= 1.35;                 // зосереджені удари по кількох головних цілях
    return v * (0.75 + Math.random() * 0.5);
  };
  const top = C.list.filter(inReach).map(o => [o, sc(o)]).sort((a, b) => b[1] - a[1]).slice(0, 18);
  if (!top.length) return null;
  const w = v => Math.pow(v, 1.4);
  let r = Math.random() * top.reduce((s, x) => s + w(x[1]), 0);
  for (const [o, v] of top){ r -= w(v); if (r <= 0) return o; }
  return top[0][0];
}
/* точка заходу на ціль з довільного напрямку (над Україною, Росією або морем) */
/* етап 7.43: обманливі заходи — точка заходу там, де менше ППО противника; у «хибному напрямку» — з протилежного боку,
   у «кількох напрямках» — по черзі з трьох секторів */
function botVia(sd, o, W){
  const B = BOT[sd], S = (B && B.sc) || {}, foe = other(sd);
  let ax = null;
  if (S.feint && B.x >= S.feint.until) ax = brg(S.feint.c, o.c);
  else if (S.axes){ B.axI = (B.axI | 0) + 1; ax = S.axes[B.axI % S.axes.length]; }
  const ads = []; for (const u of ADS.units.values()) if (u.side === foe && !AD_TYPES[u.key].air && !AD_TYPES[u.key].gun) ads.push(u);
  let best = null, bs = Infinity;
  for (let i = 0; i < 10; i++){
    const b = ax != null ? ax + (Math.random() - 0.5) * 70 : Math.random() * 360, r = 45 + Math.random() * 90, p = offKm(o.c, Math.sin(b * D2R) * r, Math.cos(b * D2R) * r);
    if (foreignAt(p)) continue;
    const m = [(p[0] + o.c[0]) / 2, (p[1] + o.c[1]) / 2];
    let thr = 0; for (const u of ads){ const R = AD_TYPES[u.key].r; if (hav(u.pos, p) <= R) thr += 1; if (hav(u.pos, m) <= R) thr += 0.6; }
    const v = thr + Math.random() * 0.9;
    if (v < bs){ bs = v; best = p; }
  }
  return best;
}
/* ======================================================================
   ЕТАП 7.43 — СЦЕНАРІЇ АТАКИ БОТА (реалістичні, стратегічні, обманливі)
   Кожен цикл атаки бот обирає стратегічну мету (по чому бити) і тактичний прийом (як обдурити ППО):
   • мета: енергетика (ТЕЦ), паливо (НПЗ, порти експорту), управління (урядові будівлі, радари ППО, аеродроми),
     логістика (залізничні, логістичні вузли, порти) або ВПК (заводи з повними складами);
   • прийом: хибний напрямок (БпЛА відтягують ППО в іншу область, ракети — з протилежного боку),
     приманки попереду (Гербери й Пародії — по тих самих цілях перед ракетами), подвійний удар (повторна хвиля
     через 35–75 хв), перевантаження ППО (усе — в одну область, щільними хвилями), тиша перед ударом (пауза — і
     раптовий масований удар), удар з кількох напрямків (заходи з трьох секторів по черзі).
   Сценарій не розкривається суперникові. Міжконтинентальних ракет бот не застосовує; Орєшнік — лише з певним
   шансом і не більше одного за атаку.
   ====================================================================== */
const BOT_SC_MAIN = {
  energy: { n: "Енергетичний удар", w: { tec: 3.4, npz: 1.3, lrail: 1.2, fac: 0.8, gov: 0.8, city: 0.35 }, side: { ru: 3, ua: 1.1 } },
  fuel:   { n: "Паливна блокада", w: { npz: 3.4, lport: 2, lrail: 1.3, tec: 1.1, city: 0.35 }, side: { ru: 1.1, ua: 3 } },
  decap:  { n: "Удар по управлінню", w: { gov: 3.6, post: 2, air: 1.4, fighter: 1.6, strat: 1.6, city: 0.5 }, side: { ru: 1.4, ua: 1.1 }, ore: 0.15 },
  logi:   { n: "Логістичний розрив", w: { lrail: 2.6, llog: 2.2, lport: 2.2, npz: 1.3, city: 0.35 }, side: { ru: 1.3, ua: 1.6 } },
  ind:    { n: "Удар по ВПК", w: { fac: 2.4, tec: 1.2, city: 0.4 }, side: { ru: 1.5, ua: 1.5 } }
};
const BOT_SC_TAC = {
  feint:  { n: "Хибний напрямок", w: 1.4 },
  decoy:  { n: "Приманки попереду", w: 1.3 },
  double: { n: "Подвійний удар", w: 1 },
  sat:    { n: "Перевантаження ППО", w: 1 },
  pause:  { n: "Тиша перед ударом", w: 0.9 },
  multi:  { n: "Удар з кількох напрямків", w: 1.1 }
};
const ORE_P = { easy: 0.12, normal: 0.2, hard: 0.3 };
function botScen(sd, B, W){
  const foe = other(sd), prev = B.sc || {};
  const mk = Object.keys(BOT_SC_MAIN).filter(k => k !== prev.main), main = mk[pickW(mk.map(k => BOT_SC_MAIN[k].side[sd] || 1))];
  const tk = Object.keys(BOT_SC_TAC).filter(k => k !== prev.tac);
  let tac = tk[pickW(tk.map(k => BOT_SC_TAC[k].w))];
  const M = BOT_SC_MAIN[main], S = { main, tac, w: M.w };
  const live = OBJS.filter(o => o.side === foe && o.t !== "city" && GAME.obj[o.i] > 0);
  const top = live.map(o => [o, objValue(o) * (M.w[o.t] || 1)]).sort((a, b) => b[1] - a[1]);
  const cap = OBJS.find(o => o.side === foe && o.t === "city" && o.n === CAPITAL[foe]);
  const mainC = top.length ? top[0][0].c.slice() : cap ? cap.c.slice() : FOE_C[sd].slice();
  if (tac === "feint"){
    const far = OBJS.filter(o => o.side === foe && o.t === "city" && objTier(o) <= 1 && hav(o.c, mainC) > 280);
    const f = far.length ? pickOne(far) : null;
    if (f) S.feint = { c: f.c.slice(), r: 150, until: 0.42 + Math.random() * 0.1 }; else tac = S.tac = "multi";
  }
  if (tac === "sat"){ S.zone = { c: mainC, r: 170 }; S.gapK = 0.8; S.batK = 1.6; }
  if (tac === "pause"){ const a = 0.4 + Math.random() * 0.07; S.pause = [a, a + 0.15 + Math.random() * 0.05]; }
  if (tac === "double") S.tap = true;
  if (tac === "decoy") S.decoy = true;
  if (tac === "multi"){ const b0 = Math.random() * 360; S.axes = [b0, b0 + 120, b0 + 240]; }
  S.n = M.n + " · " + BOT_SC_TAC[tac].n;
  B.sc = S; B.tap = {}; B.axI = 0; B.x = 0;
  (GAME.botScen || (GAME.botScen = [])).push([sd, S.n]);
  // Орєшнік: шанс на цей цикл (за складністю; удар по управлінню — частіше), пуск — у другій половині циклу
  B.ore = null;
  if (sd === "ru" && WEAPONS.oreshnik && canAttack(sd) && (GAME.mode === "free" || (MODES[GAME.mode].ars && MODES[GAME.mode].ars.ru)) &&
      SITES.some(s => !s.off && siteSide(s) === "ru" && weaponsFor(s).includes("oreshnik")) && Math.random() < (ORE_P[GAME.diff] || ORE_P.normal) + (M.ore || 0))
    B.ore = { at: 0.6 + Math.random() * 0.3, done: false };
}
/* вага цілі за метою сценарію (і зоною перевантаження) — для вибору головних цілей */
function botScW0(B, o){
  const S = B && B.sc; if (!S) return 1;
  let k = (S.w && S.w[o.t]) || 1;
  if (S.zone && hav(o.c, S.zone.c) > S.zone.r) k *= 0.08;
  return k;
}
function botScW(B, o, key, cls){
  const S = B && B.sc; if (!S) return 1;
  let k = botScW0(B, o);
  if (S.feint){
    const inF = hav(o.c, S.feint.c) <= S.feint.r;
    if (B.x < S.feint.until){ if (cls === "drone" || cls === "tac" || cls === "jet") k *= inF ? 3.2 : 0.12; }
    else if (inF) k *= 0.35;                                  // головний удар — не там, куди відтягнули ППО
  }
  if (S.decoy && isDecoy(key) && B.focus && B.focus.includes(o.i)) k *= 2.6;
  if (S.tap && B.tap){ const t = B.tap[o.i]; if (t && GAME.clock >= t && GAME.clock <= t + 90 && GAME.obj[o.i] > 0) k *= 2.6; }
  return k;
}
/* один Орєшнік за атаку: з власного запасу, а якщо його немає — з резерву (лише цей один) */
function botOreshnik(sd){
  const free = GAME.mode === "free", st = GAME.stock[sd];
  const grant = !free && (st.oreshnik | 0) < 1;
  if (grant) st.oreshnik = 1;
  const ok = botLaunch(sd, "oreshnik", 1);
  if (!ok && grant) st.oreshnik = Math.max(0, (st.oreshnik | 0) - 1);
  if (ok) GAME.oreUsed = (GAME.oreUsed | 0) + 1;
  return ok;
}
function botLaunch(sd, key, n){
  const W = WEAPONS[key];
  const sites = SITES.filter(s => !s.off && siteSide(s) === sd && weaponsFor(s).includes(key) && (!HOOKS.siteDead(s) || ((s.t === "tac" || s.t === "ua_tac") && !!carOf(s, key))));      // етап 7.32: без знищених
  if (!sites.length || !HOOKS.planCfg || !HOOKS.launchCfg) return false;
  if (W.sea){
    const ships = shipsAtSea(); if (!ships.length) return false;
    const s = pickOne(sites.filter(x => x.sea)); if (!s) return false;
    const c = { site: s, siteIdx: SITES.indexOf(s), weapon: key, variant: 0, count: n, mode: "direct", wps: [], target: null, targetName: "", spread: 0, pointMode: "site",
                cityIdx: -1, seaTgt: pickOne(ships).id, seaMode: "ship", seaPt: null };
    const plan = HOOKS.planCfg(c); if (!plan.ok) return false;
    return HOOKS.launchCfg(c);
  }
  // звідки дістає ракета: наземні рубежі — самі, авіація й кораблі — з рубежів пуску носія
  let reach = null;
  if (W.fpv) reach = o => { const d = dropPt(o.c, W.km, sd); return !!d && d.d <= W.km - 2; };          // етап 7.14 / 7.17: FPV (і України) — лише цілі біля лінії фронту          // етап 7.14: FPV — лише цілі біля лінії фронту
  else if (W.km < 450){
    reach = [];
    for (const s of sites){
      const ck = carOf(s, key), C = ck && CARRIERS[ck];
      // edge — пуск з краю рубежу, ближчого до цілі: дістає далі на радіус рубежу
      if (C && C.kind === "air") for (const z of (s.t === "tac" || s.t === "ua_tac" ? [s] : carZones(C, key))) reach.push([z.c[0], z.c[1], W.km + (W.edge ? 1 : -1) * zoneR(z) * 0.85 - 3]);
      else if (C && C.kind === "sea" && PORT_LANES[s.n] && PORT_LANES[s.n].sea && siteByName(SEA_ZONE[PORT_LANES[s.n].sea])){ const z = siteByName(SEA_ZONE[PORT_LANES[s.n].sea]); reach.push([z.c[0], z.c[1], W.km + zoneR(z) * 0.85 - 3]); }   // етап 7.18: кораблі — лише з порту, пуск у морському рубежі
      else reach.push([s.c[0], s.c[1], W.km + (W.edge ? zoneR(s) * 0.85 : -zoneR(s)) - 3]);
    }
  }
  if (telGated(sd, key)) reach = telReach(sd, key);      // етап 7.66: дальність — від справжніх позицій готових ПУ
  for (let tries = 0; tries < 8; tries++){
    const o = botTarget(sd, key, reach); if (!o) return false;
    const near = reach ? sites.filter(x => !carOf(x, key)).sort((a, b) => hav(a.c, o.c) - hav(b.c, o.c)) : [];
    const byDist = W.glide ? sites.slice().sort((a, b) => hav(a.c, o.c) - hav(b.c, o.c)) : null;   // Су-34 з авіабомбами — з найближчих аеродромів
    const s = byDist ? byDist[tries % Math.min(3, byDist.length)] : near.length && tries < 4 ? near[0] : pickOne(sites), ck = carOf(s, key);
    if (ck){ const av = carAvail(sd, ck); if (av < 1) continue; n = Math.min(n, av * carCap(CARRIERS[ck], key)); }
    // заходи з різних напрямків: частина хвилі — через точку довкола цілі
    const S = BOT[sd] && BOT[sd].sc, pv = S && ((S.feint && BOT[sd].x >= S.feint.until) || S.axes) ? 0.88 : 0.6;
    const via = !W.glide && !W.fpv && W.km > 150 && tries < 5 && Math.random() < pv ? botVia(sd, o, W) : null;
    const fp = W.fpv ? dropPt(o.c, W.km, sd) : null; if (W.fpv && !fp) continue;     // етап 7.14: FPV — пуск з найближчої до цілі точки своєї території
    const c = { site: s, siteIdx: SITES.indexOf(s), weapon: key, variant: W.img.length > 1 ? "mix" : 0, count: n,
                mode: via ? "via" : W.glide || W.fpv || W.km <= 150 ? "direct" : pickOne(["direct", "arcL", "arcR", "zigzag"]), wps: via ? [via] : [], fpvPt: fp ? fp.p : null,
                target: o.c.slice(), targetName: o.n, spread: W.ad === "drone" ? 2 : 1, pointMode: "random", cityIdx: -1, seaTgt: null, seaMode: "patrol", seaPt: null };
    const plan = HOOKS.planCfg(c);
    if (plan.ok && HOOKS.launchCfg(c)){ const B = BOT[sd]; if (B){ B.sent = B.sent || {}; B.sent[o.i] = (B.sent[o.i] || 0) + n * wDmg(key);
        // етап 7.43: «подвійний удар» — повторна хвиля по тій самій цілі через 35–75 хв (коли ППО перезаряджається, а рятувальники на місці)
        if (B.sc && B.sc.tap && o.t !== "city" && ["cruise", "ballistic", "hyper"].includes(wCls(key)) && B.tap && !B.tap[o.i]) B.tap[o.i] = GAME.clock + 35 + Math.random() * 40; }
      return true; }
  }
  return false;
}

/* ======================================================================
   ЗАПИС БОЮ (для відеохронології): кадр кожні REC.dt ігрових хвилин
   ====================================================================== */
const REC = { frames: [], dt: 1, next: 0, ev: [], al: [], alSig: "", ob: [], obVer: -1 };
const CLS_I = { drone: 0, jet: 1, rd: 2, cruise: 3, ballistic: 4, hyper: 5, icbm: 4, bomb: 3, tac: 0 };
const shotIds = new WeakMap(); let shotSeq = 1;
const shotId = s => { let id = shotIds.get(s); if (!id){ id = s.sid || shotSeq++; shotIds.set(s, id); } return id; };
function recReset(){
  const k = MODES[GAME.mode].kind;
  Object.assign(REC, { frames: [], ev: [], al: [], alSig: "", ob: [], obVer: -1, dt: k === "night" ? 1 : k === "rounds" ? 3 : k === "days" ? 5 : 2, next: 0 });
}
function recFrame(){
  if (!GAME.on) return;
  const U = [], A = [], S = [];
  for (const u of units.values()){
    const W = WEAPONS[u.key];
    let c = u.kind === "c" ? 6 : u.sea ? 7 : (W ? CLS_I[W.ad] || 0 : 0);
    U.push(u.id, u.pos[0], u.pos[1], u.hdg || 0, (u.sd === "ua" ? 1 : 0) + c * 2 + (u.fall ? 32 : 0));
  }
  for (const a of ADS.units.values()){
    const T = AD_TYPES[a.key], fly = T.air && a.state !== "base" && a.state !== "reload";
    A.push(a.id, a.pos[0], a.pos[1], a.hdg || 0, (a.side === "ua" ? 1 : 0) + (T.air ? 2 : 0) + (fly ? 4 : 0), T.air ? 0 : T.r);
  }
  for (const s of ADS.shots) S.push(shotId(s), s.pos[0], s.pos[1], s.hdg, s.sd === "ua" ? 1 : 0);
  const st = GAME.st;
  REC.frames.push({ c: gameClock(), ph: GAME.phase, att: GAME.attacker, u: new Float32Array(U), a: new Float32Array(A), s: new Float32Array(S), e: REC.ev,
    n: [st.ua.launched, st.ru.launched, st.ua.downed, st.ru.downed, st.ua.objHits, st.ru.objHits, st.ua.destroyed, st.ru.destroyed, Math.round(st.ua.pts), Math.round(st.ru.pts)] });
  REC.ev = [];
  const sig = [...ALERTS.entries()].map(([id, a]) => id + (a.type === "red" ? "r" : "y")).join(",");
  if (sig !== REC.alSig){ REC.alSig = sig; REC.al.push({ f: REC.frames.length - 1, list: [...ALERTS.entries()].map(([id, a]) => [id, a.type === "red" ? 2 : 1]) }); }
  if (GAME.objVer !== REC.obVer){ REC.obVer = GAME.objVer; REC.ob.push({ f: REC.frames.length - 1, hp: new Float32Array(GAME.obj) }); }
}
function recStep(){
  if (!GAME.on || GAME.phase !== "run") return;
  if (GAME.clock >= REC.next){ REC.next = GAME.clock + REC.dt; recFrame(); }
}
const FXK = { ground: 0, kill: 1, crash: 2, ship: 4 };
function recFx(p, k){ if (GAME.on && FXK[k] !== undefined && REC.ev.length < 400) REC.ev.push(p[0], p[1], FXK[k]); }

