const strHash = s => { let h = 2166136261; for (const ch of s) h = Math.imul(h ^ ch.codePointAt(0), 16777619); return h >>> 0; };
const FACS = [];
function facPlace(sd, name, k, sea){
  const C = FAC_CITY[name] || [30, 50, 0], c = [C[0], C[1]];
  if (C[2] < 0) return c;
  const d0 = [2.8, 4.6, 7.2][C[2]], pref = C[3] != null ? C[3] : strHash(name) % 360;
  const ok = p => placeOK(sd, p) && !seaWater(p) && FACS.every(f => hav(f.c, p) > 4.5);
  const at = (a, r) => offKm(c, Math.sin(a * D2R) * r, Math.cos(a * D2R) * r);
  if (sea){
    // суша, від якої до моря не більше ~2 км
    let best = null, bs = Infinity;
    for (let r = 1.5; r <= 10.5; r += 1.5) for (let a = 0; a < 360; a += 15){
      const p = at(a, r); if (!ok(p)) continue;
      if (![0, 45, 90, 135, 180, 225, 270, 315].some(b => seaWater(offKm(p, Math.sin(b * D2R) * 2, Math.cos(b * D2R) * 2)))) continue;
      const sc = Math.abs(r - 3.5) + Math.abs(((a - pref - k * 60) % 360 + 540) % 360 - 180) * 0.012;
      if (sc < bs){ bs = sc; best = p; }
    }
    if (best) return best;
  }
  for (let i = 0; i < 40; i++){
    const a = pref + (k % 2 ? 1 : -1) * Math.ceil(k / 2) * 55 + (i % 2 ? 1 : -1) * Math.ceil(i / 2) * 23, r = d0 * (1 + 0.22 * (Math.floor(i / 8)));
    const p = at(a, r); if (ok(p)) return p;
  }
  return at(pref + k * 55, d0);
}
