function geoDec(str, prec){
  prec = prec || 1e4; const out = []; let i = 0, x = 0, y = 0;
  while (i < str.length){
    const v = [0, 0];
    for (let k = 0; k < 2; k++){ let sh = 0, r = 0, b; do { b = str.charCodeAt(i++) - 63; r |= (b & 0x1f) << sh; sh += 5; } while (b >= 0x20); v[k] = r & 1 ? ~(r >> 1) : r >> 1; }
    y += v[0]; x += v[1]; out.push([x / prec, y / prec]);
  }
  return out;
}
