  for (const [v, d] of list){ if (d > 160) break; const p = railPath(from, v.i); if (p) return { node: v.i, path: p, d }; }
  // далекий завод (немає станції поруч): потягом до найближчої досяжної станції, якщо це суттєво ближче, далі — дорогами
