  const deg = new Int32Array(n + 1);
  for (let i = 0; i < E.length; i += 3){ deg[E[i]]++; deg[E[i + 1]]++; }
  const off = new Int32Array(n + 1); for (let i = 0; i < n; i++) off[i + 1] = off[i] + deg[i];
