    if (live()){ const hp = GAME.obj[v.oi]; h += `Міцність: ${Math.round(hp / OBJS[v.oi].hp * 100)}%${hp <= 0 ? " — знищено" : hp < OBJS[v.oi].hp ? " — пошкоджено" : ""}<br>`; }
    const al = infAlert(v); h += `Повітряна тривога: ${al === "red" ? "<b style=\"color:#ff5a4d\">червона</b>" : al === "yellow" ? "<b style=\"color:#ffd21a\">жовта</b>" : "немає"}`;
