  /* ---------- фонова демонстрація в меню: повітряні цілі летять над мапою ---------- */
  const DEMO = { on: false, ready: false, list: [], last: 0, acc: 0, lastSet: 0 };
  const DEMO_RU = ["shahed", "shahed", "shahed", "shahed", "gerbera", "geran3", "geran5", "kalibr", "kh101", "kh101", "iskander", "kn23", "iskanderk", "kh555", "onyx"];
