    const zoom = Math.max(2.6, Math.min(Math.log2(w / (PX_PER_RAD_Z0 * lonR)), Math.log2(h / (PX_PER_RAD_Z0 * (y1 - y0)))));
    const scale = PX_PER_RAD_Z0 * Math.pow(2, zoom);
    return { center: [(b[0][0] + b[1][0]) / 2 + (pad.right - pad.left) / 2 / scale / D2R, unMercY((y0 + y1) / 2 + (pad.top - pad.bottom) / 2 / scale)], zoom };
