    const f = FACS[FP.i], S = GAME.facSel && GAME.facSel[f.i], E = ecoE(f.side), o = OBJS[f.oi];
    const hp = GAME.obj ? GAME.obj[f.oi] : o.hp, dead = hp <= 0;
    const sig = [FP.i, S ? S.p + (S.on ? 1 : 0) : "-", E && E.on ? 1 : 0, dead ? 1 : 0, facMine(f) ? 1 : 0, S7.lang ? S7.lang() : ""].join("|");
    if (sig !== FP.sig){ FP.sig = sig; facBuild(); }
    const box = $("fpBody"), q = k => box.querySelector(`[data-fp="${k}"]`);
    const set = (k, tx) => { const el = q(k); if (el && el.textContent !== S7.tr(tx)) el.textContent = tx; };
    const pct = Math.round(Math.max(0, hp) / o.hp * 100);
    const run = E && E.on && prodOn(f.side);
    set("hp", dead ? "завод знищено" : `${pct}% · ${!S || !S.on ? "зупинено" : run ? "працює" : "простій"}` + (!dead && hp < o.hp - 0.01 ? " · пошкоджено" : ""));
