    const pr = J && J.pid === S.p ? Math.max(0, Math.min(1, 1 - Math.max(0, J.left) / J.h)) : 0;
    const pn = GAME.facParts ? GAME.facParts[f.i] || 0 : 0, need = partsOf(S.p), lack = !J && pn < need && GAME.facShort && GAME.facShort[f.i];
    set("parts", `${fmtN(pn)} дет.`); set("pinc", `${fmtN(GAME.lgv && GAME.lgv.inc ? GAME.lgv.inc[f.i] || 0 : 0)} дет.`);
