    const ib = q("inv"); if (ib && ib._h !== ih){ ib._h = ih; ib.innerHTML = ih; }
    set("invn", items.length ? `${items.length} вид.` : "");
    const msg = !facMine(f) ? (GAME.spec ? "Режим глядача — лише перегляд" : "") : dead ? "" : S.on ? (/^[wc]:/.test(S.p) ? "Готова продукція додається до панелі пусків" : "Готова продукція додається до панелі ППО") : "Завод не працює — гроші не витрачаються";
