        const a = c[k - 1], b = c[k];
        const x0 = Math.floor(Math.min(a[0], b[0]) / MS_CELL), x1 = Math.floor(Math.max(a[0], b[0]) / MS_CELL);
        const y0 = Math.floor(Math.min(a[1], b[1]) / MS_CELL), y1 = Math.floor(Math.max(a[1], b[1]) / MS_CELL);
