    for (const f of (BV.mask.features || [])){ const p = geomPath(new Path2D(), f.geometry); g.fillStyle = "#171a1f"; g.fill(p); g.strokeStyle = "#272b31"; g.lineWidth = 0.8; g.stroke(p); }
