      const [x, y] = P(lon, lat), col = fall ? "255,170,70" : sd ? "90,165,255" : "255,80,70";
      let px = x, py = y, a = 0.55;
      for (const [pj, m] of past){ const o = m.get(id); if (o === undefined) break; const PU = F[pj].u, [qx, qy] = P(PU[o + 1], PU[o + 2]);
        g.strokeStyle = `rgba(${col},${a})`; g.lineWidth = 1.4; g.beginPath(); g.moveTo(px, py); g.lineTo(qx, qy); g.stroke(); px = qx; py = qy; a *= 0.55; }
