    gr = g.createLinearGradient(0, VH - VBOT, 0, VH); gr.addColorStop(0, "rgba(5,6,8,0)"); gr.addColorStop(1, "rgba(5,6,8,.96)"); g.fillStyle = gr; g.fillRect(0, VH - VBOT - 6, VW, VBOT + 6);
    g.textBaseline = "alphabetic"; g.textAlign = "left";
    g.font = '800 30px "Exo 2", system-ui, sans-serif'; g.fillStyle = "#f1f3f5"; g.fillText("SKYDOMINION", 28, 44);
    const w = g.measureText("SKYDOMINION ").width; g.fillStyle = "#ff3b30"; g.shadowColor = "#ff3b30"; g.shadowBlur = 12; g.fillText("", 28 + w, 44); g.shadowBlur = 0;
    g.font = '600 14px "JetBrains Mono", ui-monospace, monospace'; g.fillStyle = "#a3aab2"; g.fillText(S7.tr("Відеохронологія · " + MODES[GAME.mode].n).toUpperCase(), 30, 66);
    g.textAlign = "right"; g.font = '600 32px "JetBrains Mono", ui-monospace, monospace'; g.fillStyle = "#fff"; g.fillText(clockHM(c), VW - 28, 44);
    g.font = '600 14px "JetBrains Mono", ui-monospace, monospace'; g.fillStyle = "#a3aab2";
    g.fillText(S7.tr(`ДЕНЬ ${dayOf(c)}` + (A.ph === "prep" ? " · ПІДГОТОВКА" : MODES[GAME.mode].att === "turn" ? ` · УДАР: ${SIDE_N[A.att] || ""}` : "")).toUpperCase(), VW - 28, 66);
    g.textAlign = "left"; g.font = '600 15px "JetBrains Mono", ui-monospace, monospace';
    g.fillStyle = "#8ec1ff"; g.fillText(S7.tr(`УКРАЇНА  запущено ${NN[0]} · збито ${NN[2]} · влучань ${NN[4]} · знищено об'єктів ${NN[6]}`), 28, VH - 40);
    g.fillStyle = "#ff9a92"; g.fillText(S7.tr(`РОСІЯ    запущено ${NN[1]} · збито ${NN[3]} · влучань ${NN[5]} · знищено об'єктів ${NN[7]}`), 28, VH - 17);
    g.textAlign = "right"; g.font = '800 30px "Exo 2", system-ui, sans-serif';
    const sU = fmtN(NN[8]), sR = fmtN(NN[9]); g.fillStyle = "#ff7d74"; g.fillText(sR, VW - 28, VH - 18); const wr = g.measureText(sR).width;
