      const blob = await vidRecord(S7.vidDur || vidDur(), t => { if (bar) bar.style.width = (t * 100).toFixed(1) + "%"; if (stx) stx.textContent = `Запис відео… ${Math.round(t * 100)}%`; });
      if (!blob){ if (stx) stx.textContent = "Запис скасовано"; return; }
