      const a = document.createElement("a"), ext = blob.type.includes("mp4") ? "mp4" : "webm", d = new Date();
      a.href = URL.createObjectURL(blob); a.download = `SkyDominion_${GAME.mode}_${d.toISOString().slice(0, 10)}_${String(d.getHours()).padStart(2, "0")}${String(d.getMinutes()).padStart(2, "0")}.${ext}`;
      document.body.appendChild(a); a.click(); setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 4000);
      if (stx) stx.textContent = `Відео збережено · ${(blob.size / 1048576).toFixed(1).replace(".", ",")} МБ`;
