      const C = CARRIERS[u.key]; if (!C || C.kind !== "air" || PH.carSeen.has(u.id)) continue;
      { const chc = C.side === "ru" ? "ua" : "ru"; if (fogSide() && (chc !== fogSide() || (!GAME.puppet && !fogKnownThreat(chc, u)))) continue; }      // етап 7.60: зліт — лише якщо носій виявлено РЛС
