/* ---------- етап 7.37: сповіщення каналів у стилі гри (поки телефон закрито або відкрито інший канал) ---------- */
function phNote(p){
  if (!PH.notify[p.ch] || !GAME.on || document.body.classList.contains("s7-menu")) return;
  if (PH.open && (PH.ch === p.ch || !PH.ch || innerWidth < 640)) return;      // на телефоні з відкритим телефоном — лише лічильники в Bgram
  let el = document.getElementById("bgNote");
  if (!el){
    el = document.createElement("div"); el.id = "bgNote"; el.className = "hud panel notr"; el.setAttribute("translate", "no"); document.body.appendChild(el);
    el.addEventListener("click", e => {
      if (e.target.closest("[data-bn=x]")){ el.classList.remove("on"); clearTimeout(PH.noteT); return; }
      const ch = el.dataset.ch; el.classList.remove("on"); clearTimeout(PH.noteT);
      if (!PH.open) phToggle(true);
      PH.ch = ch; PH.sig = ""; phRender(true); const bd = document.getElementById("bgBody"); if (bd) bd.scrollTop = bd.scrollHeight;
    });
  }
  const now = performance.now(), same = el.classList.contains("on") && now - (PH.noteAt || 0) < 4500;
  PH.noteN = same && el.dataset.ch === p.ch ? (PH.noteN || 0) + 1 : 0; PH.noteAt = now;
  const T = phT(), C = PH_CH[p.ch];
  el.dataset.ch = p.ch; el.classList.toggle("ru", p.ch === "ru"); el.classList.toggle("ua", p.ch === "ua");
  el.innerHTML = `<div class="bn-h">${phAv(p.ch)}<span class="bn-t"><b>${C.n}<em class="bg-ok">✔</em></b><small>BGRAM · ${clockHM(p.t)}</small></span>` +
    (PH.noteN ? `<i class="bn-n">+${PH.noteN}</i>` : "") + `<button class="bn-x" data-bn="x" aria-label="${T.close}">×</button></div>` +
    `<div class="bn-tx">${phE(phText(p))}</div><i class="bn-bar"></i>`;
  // на телефоні — під сповіщенням гри, якщо воно зараз видно
  const ts = document.getElementById("toast"), tr0 = ts && ts.style.display === "block" ? ts.getBoundingClientRect() : null;
  el.style.top = innerWidth < 640 ? Math.round(tr0 ? tr0.bottom + 8 : 112) + "px" : "";
  if (!el.classList.contains("on")){ void el.offsetWidth; el.classList.add("on"); }      // уже видно — лише новий текст і смужка, без повторного виїзду
  clearTimeout(PH.noteT); PH.noteT = setTimeout(() => el.classList.remove("on"), 5200);
}
function phUnread(){ let n = 0; for (const ch of ["ua", "ru"]){ const L = PH.posts[ch]; n += L.filter(p => p.id > PH.seen[ch]).length; } return n; }
function phRender(force){
  if (!PH.open || !PH.el) return;
  const T = phT(), L = phLang(), $b = id => document.getElementById(id);
  $b("bgClock").textContent = clockHM(phNow());
  const sig = [PH.sig, PH.ch, L, PH.notify.ua, PH.notify.ru, Math.floor(SIM.t)].join("|");
  if (!force && sig === PH.rsig) return; PH.rsig = sig;
  if (!PH.ch){
    $b("bgTop").innerHTML = `<div class="bg-logo"><b>B</b>gram</div><span class="bg-ttl">${T.chats}</span><button class="bg-x" data-bg="close" aria-label="${T.close}">×</button>`;
    $b("bgBody").innerHTML = ["ua", "ru"].map(ch => {
      const P = PH.posts[ch], last = P[P.length - 1], un = P.filter(p => p.id > PH.seen[ch]).length;
      return `<button class="bg-row" data-bg="ch" data-v="${ch}">${phAv(ch)}<span class="bg-rt"><b>${PH_CH[ch].n}<em class="bg-ok">✔</em>${PH.notify[ch] ? "" : `<em class="bg-mt" title="${T.muted}">🔕</em>`}</b><small>${last ? phE(phText(last)) : phE(phSubs(PH_CH[ch].subs) + " " + T.subs)}</small></span>` +
        `<span class="bg-rm"><small>${last ? clockHM(last.t) : ""}</small>${un ? `<i class="bg-bd">${un > 99 ? "99+" : un}</i>` : ""}</span></button>`;
    }).join("");
    $b("bgFoot").innerHTML = "";
    return;
  }
  const ch = PH.ch, C = PH_CH[ch], P = PH.posts[ch];
  $b("bgTop").innerHTML = `<button class="bg-bk" data-bg="back" aria-label="${T.back}">‹</button>${phAv(ch)}<span class="bg-rt"><b>${C.n}<em class="bg-ok">✔</em></b><small>${phSubs(C.subs)} ${T.subs}</small></span><button class="bg-x" data-bg="close" aria-label="${T.close}">×</button>`;
  const body = $b("bgBody"), atEnd = body.scrollHeight - body.scrollTop - body.clientHeight < 40;
  body.innerHTML = P.length ? P.slice(-60).map(p => {
    const rx = p.acc.map((v, i) => [PH_RX[i], Math.round(v)]).filter(x => x[1] > 0).sort((a, b) => b[1] - a[1]);
    const views = Math.round(p.acc.reduce((a, b) => a + b, 0) * 34 + 900 * (PH.byK && p.city && PH.byK.get(p.city) ? PH.byK.get(p.city).w : 2) * Math.min(1, (SIM.t - p.st) / 20 + 0.1));
    return `<div class="bg-msg${p.k === "alert" || p.k === "alertm" || p.k === "alerto" ? " al" : p.k.startsWith("clear") ? " cl" : p.k === "hit" ? " hit" : ""}">` +
      `<div class="bg-tx"${p.city ? ` data-bg="city" data-v="${phE(p.city)}"` : ""}>${phE(phText(p))}</div><div class="bg-sub">${phE(T.sub.replace("{ch}", C.n))}</div>` +
      (rx.length ? `<div class="bg-rx">${rx.map(([e, n]) => `<span>${e}<b>${phFmt(n)}</b></span>`).join("")}</div>` : "") +
      `<div class="bg-meta">👁 ${phFmt(views)} · ${clockHM(p.t)}</div></div>`;
  }).join("") : `<div class="bg-empty">${T.empty}</div>`;
  if (atEnd || force) body.scrollTop = body.scrollHeight;
  if (P.length) PH.seen[ch] = P[P.length - 1].id;
  $b("bgFoot").innerHTML = `<button class="bg-join${PH.notify[ch] ? "" : " on"}" data-bg="mute">${PH.notify[ch] ? T.mute : T.unmute}</button>`;
}
setInterval(() => { try { phStep(); } catch (e) { console.warn("phone", e); } }, 700);
S7.phone = { toggle: phToggle, unread: phUnread, isOpen: () => PH.open, label: () => phT().phone, state: PH, step: phStep, text: phText };

