/* ---------- каталог: уся техніка гри (для арсеналу) і платна (для майданчика) ---------- */
const BC_ITEMS = {}, BC_LIST = [];
(() => {
  const subA = T => T.air ? (T.heli ? "Вертольоти" : "Літаки") : T.drone ? (T.manOnly ? "Ручне наведення" : "Автоматичне наведення") : T.ship ? "Кораблі ППО" :
    T.r >= 60 ? "Далекого радіуса" : T.r >= 20 ? "Середнього радіуса" : "Ближнього радіуса";
  const subW = w => ({ tac: "Тактичні БпЛА", drone: "Ударні БпЛА", jet: "Реактивні БпЛА", rd: "Ракетно-дронові", bomb: "Авіабомби", icbm: "МБР", hyper: "Гіперзвукові ракети",
                       ballistic: "Балістичні ракети" }[w.ad] || (w.cls === "sea" ? "Морські дрони" : w.cls === "missile" ? "Ракети" : "Крилаті ракети"));
  const paid = {}; for (const sd of ["ua", "ru"]) for (const c in BC_PAID[sd]) for (const k of BC_PAID[sd][c]) paid[(c === "tgt" ? "w:" : "a:") + k] = c;
  for (const k in AD_TYPES){
    const T = AD_TYPES[k]; if (!T.air && !AD_SPRITES["ad_" + k]) continue;
    const id = "a:" + k, cat = T.air ? "air" : T.drone ? "dr" : T.ship ? "ship" : "ad";
    BC_ITEMS[id] = { id, k: "a", key: k, side: T.side || "ua", cat, sub: subA(T), paid: !!paid[id], price: paid[id] ? BC_PRICE[k] || 100 : 0 };
  }
  for (const k in WEAPONS){
    const w = WEAPONS[k]; if (w.child || k === "rv" || !w.img || !SPRITES[w.img[0]]) continue;
    const id = "w:" + k;
    BC_ITEMS[id] = { id, k: "w", key: k, side: w.side || "ru", cat: "tgt", sub: subW(w), paid: !!paid[id], price: paid[id] ? BC_PRICE[k] || 100 : 0 };
  }
  const ord = { ad: 0, dr: 1, air: 2, ship: 3, tgt: 4 };
  BC_LIST.push(...Object.values(BC_ITEMS).sort((a, b) => (a.side === b.side ? 0 : a.side === "ua" ? -1 : 1) || ord[a.cat] - ord[b.cat] || b.price - a.price));
})();
const bcName = it => it.k === "a" ? AD_TYPES[it.key].n : WEAPONS[it.key].n;
const bcImg = it => it.k === "a" ? adSrc(it.key) : SPRITES[WEAPONS[it.key].img[0]].src;
const bcOwned = it => !it.paid || PROF.own.includes(it.id);
/* контейнери: шанс випадіння ∝ ціна^-1,25 (дешевше — частіше); ціна контейнера ≈ 0,85 × очікуваної вартості */
const BC_BOX = {};
for (const sd of ["ua", "ru"]) for (const t in BC_BOXT){
  const ids = BC_PAID[sd][BC_BOXT[t][1]].map(k => (t === "str" ? "w:" : "a:") + k).filter(id => BC_ITEMS[id]);
  const w = ids.map(id => Math.pow(BC_ITEMS[id].price, -1.25)), S = w.reduce((a, b) => a + b, 0);
  const drops = ids.map((id, i) => ({ id, ch: w[i] / S })).sort((a, b) => b.ch - a.ch);
  const ev = drops.reduce((a, d) => a + d.ch * BC_ITEMS[d.id].price, 0);
  BC_BOX[sd + "_" + t] = { id: sd + "_" + t, side: sd, t, drops, price: Math.max(20, Math.round(0.85 * ev / 5) * 5) };
}
const BC_BOX_ORDER = ["ua_def", "ua_int", "ua_air", "ua_str", "ru_def", "ru_int", "ru_air", "ru_str"];
const bcCheap = sd => BC_BOX_ORDER.filter(b => b.startsWith(sd)).sort((a, b) => BC_BOX[a].price - BC_BOX[b].price).slice(0, 2);
const bcPct = v => { const p = v * 100; return (p >= 10 ? p.toFixed(0) : p.toFixed(1)).replace(".", ",") + "%"; };

