/* вхід для адміністрації: адреса сайту з ?admin → ключ власників (діє 2 рази) → цей пристрій отримує адмін-панель */
const ADM_LOGIN = (() => { try { return /(^|[?&#])admin(=|&|$)/i.test(location.search.slice(1) + "&" + location.hash.slice(1)); } catch (e) { return false; } })();
function admLoginOpen(n){
  n = n | 0;
  if (!S7.modal || !SITE.on){ if (n < 30) return setTimeout(() => admLoginOpen(n + 1), 1000); return toast("Немає зв'язку із сервером гри — спробуйте пізніше"); }
  if (SITE.admin){ toast("Цей пристрій уже має права адміністратора"); return admOpen(); }
  S7.modal(`<h3 class="adm-h">${tickSvg("#ffcc33", 20)} Вхід для адміністрації</h3><div class="sub">Введіть ключ власників — цей пристрій отримає доступ до адмін-панелі (кнопка «Адмін панель» у профілі).</div>` +
    `<div class="s7row">${admIn("admLk", "Ключ власників", 40, 'autocapitalize="off" autocorrect="off"')}</div><div class="mm-note" id="admLkM"></div>` +
    `<div class="foot"><button class="s7b ghost" data-s7="mdlx">Скасувати</button><button class="s7b" data-adm="login">Увійти</button></div>`, false, "admlogin");
  setTimeout(() => { const e = admEl("admLk"); if (e) e.focus(); }, 80);
}
/* ключ власників → права адміністратора на цьому пристрої (без обмежень кількості пристроїв) */
async function admKeyTry(raw){
  const key = String(raw || "").trim().toLowerCase().replace(/[\s-]+/g, "");
  if (!SITE.on) return { ok: false, err: "net" };
  const r = await siteCall("/api/activate", { key, own: 1, ua: navigator.userAgent }).catch(() => null);
  if (!r || !r.ok || !r.admin) return { ok: false, err: r && r.err === "bad" ? "bad" : "net" };
  if (r.dev && r.dev !== SITE.dev){ SITE.dev = r.dev; try { localStorage.setItem("bv2-dev", r.dev); } catch (x) {} }
  try { localStorage.setItem("bv2-adm", "1"); } catch (x) {}
  SITE.admin = true; if (SITE.adm instanceof Set) SITE.adm.add(PROF.id);
  S7.menuRender && S7.menuRender(); sitePing(); setTimeout(siteTicks, 4000);
  toast("Права адміністратора активовано — «Адмін панель» у профілі", "ok");
  return { ok: true };
}
async function admLogin(b){
  const e = admEl("admLk"), m = admEl("admLkM"), key = e ? e.value.trim() : "";
  const say = t => { if (m){ m.textContent = t; m.style.color = "#ff8a80"; } };
  if (!key) return say("Введіть ключ власників");
  if (b) b.disabled = true;
  const r = await admKeyTry(key);
  if (b) b.disabled = false;
  if (!r.ok) return say(r.err === "bad" ? "Ключ недійсний — перевірте, чи правильно його введено" : ADM_ERR.net);
  S7.modalClose && S7.modalClose(); S7.menuRender && S7.menuRender();
}
